// Tiny i18n: t('key', 'English default with {vars}', { vars }).
// Dictionaries live in /i18n/<lang>.json (generated by scripts/extract-i18n.mjs + translated).

export const LANGS = [
  { id: 'en', name: 'English', native: 'English' },
  { id: 'de', name: 'German', native: 'Deutsch' },
  { id: 'fr', name: 'French', native: 'Français' },
  { id: 'es', name: 'Spanish', native: 'Español' },
  { id: 'it', name: 'Italian', native: 'Italiano' },
];

let lang = 'en';
let dict = {};
const listeners = new Set();

export function currentLang() {
  return lang;
}

export function guessLang() {
  const nav = (navigator.languages || [navigator.language || 'en']).map((l) => l.slice(0, 2).toLowerCase());
  return nav.find((l) => LANGS.some((x) => x.id === l)) || 'en';
}

export async function setLang(next) {
  const id = LANGS.some((l) => l.id === next) ? next : 'en';
  let d = {};
  if (id !== 'en') {
    try {
      d = await (await fetch(`/i18n/${id}.json`)).json();
    } catch {
      d = {};
    }
  }
  lang = id;
  dict = d;
  document.documentElement.lang = id;
  for (const fn of listeners) fn(id);
  return id;
}

export function onLangChange(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

function fill(s, vars) {
  if (!vars) return s;
  return s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined || vars[k] === null ? m : String(vars[k])));
}

/**
 * Translate. Plurals: pass { count } and give the default as "one|other".
 */
export function t(key, fallback = key, vars) {
  let s = dict[key] ?? fallback;
  if (vars && typeof vars.count === 'number' && s.includes('|')) {
    const [one, other] = s.split('|');
    s = vars.count === 1 ? one : other;
  }
  return fill(s, vars);
}

/** Relative time ("2 min ago") in the current language. */
export function ago(ts) {
  if (!ts) return '–';
  const rtf = new Intl.RelativeTimeFormat(lang, { numeric: 'auto' });
  const s = Math.round((ts - Date.now()) / 1000);
  if (Math.abs(s) < 10) return t('time.now', 'just now');
  if (Math.abs(s) < 60) return rtf.format(s, 'second');
  const m = Math.round(s / 60);
  if (Math.abs(m) < 60) return rtf.format(m, 'minute');
  const h = Math.round(m / 60);
  if (Math.abs(h) < 24) return rtf.format(h, 'hour');
  return rtf.format(Math.round(h / 24), 'day');
}
